solution:
def range_sums(nums: list[int], queries: list[list[int]]) -> list[int]:
    prefix = [0]                         # prefix[i] = sum of the first i numbers
    for x in nums:
        prefix.append(prefix[-1] + x)
    return [prefix[hi + 1] - prefix[lo] for lo, hi in queries]

perf.naive:
def range_sums(nums: list[int], queries: list[list[int]]) -> list[int]:
    out = []
    for lo, hi in queries:
        total = 0
        for i in range(lo, hi + 1):
            total += nums[i]
        out.append(total)
    return out
